"""Manifest/design writer only: no models, pseudo generation, or graph samples."""
import hashlib,json,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
import numpy as np

ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).parent
N20=ROOT/'reports/carla_train_expand20_v1'
def read(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for b in iter(lambda:f.read(8<<20),b''):h.update(b)
 return h.hexdigest()
def save(name,obj):
 raw=(json.dumps(obj,sort_keys=True,indent=2,allow_nan=False)+'\n').encode()
 with (OUT/name).open('xb') as f:f.write(raw)
def doc(name,s):
 with (OUT/name).open('xb') as f:f.write(s.encode('utf-8'))
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT,text=True).strip()
config=read(N20/'frozen_acquisition_config.json');manifest=read(N20/'frozen_dataset_manifest.json')
stage=Path(config['staging_root']);cache=stage/'cache_train20_v1';handoff=stage/'kaggle_compact_train20_v1'
if '--snapshot-only' in sys.argv:
 paths=subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard'],cwd=ROOT,text=True).splitlines()
 hashes={}
 for rel in sorted(set(paths)):
  p=ROOT/rel
  if p.is_file() and not p.is_relative_to(OUT):hashes[rel]=sha(p)
 outside={str(p):sha(p) for folder in [cache,handoff] for p in sorted(folder.iterdir()) if p.is_file()}
 save('initial_state.json',{'repository_sha256':hashes,'N20_cache_and_handoff_sha256':outside,'git_head':git('rev-parse','HEAD'),'git_status':git('status','--short'),'snapshot_utc':datetime.now(timezone.utc).isoformat()})
 print('Snapshot complete:',len(hashes),'repository files;',len(outside),'cache/handoff files');sys.exit(0)

base=read(OUT/'initial_state.json')
for rel,h in base['repository_sha256'].items():assert sha(ROOT/rel)==h,rel
for p,h in base['N20_cache_and_handoff_sha256'].items():assert sha(p)==h,p
assert git('rev-parse','HEAD')==base['git_head']
for rel,h in config['source_hashes'].items():assert sha(ROOT/rel)==h,rel
cr=read(N20/'cache_result.json');er=read(N20/'kaggle_artifact_result.json');cal=read(N20/'calibration_results.json')
assert sha(cache/'carla_train_cache.npz')==cr['file_sha256']
assert sha(handoff/'manifest.json')==er['export_manifest_sha256']
assert sha(N20/'frozen_dataset_manifest.json')==(N20/'frozen_dataset_manifest.sha256').read_text().strip()
assert {k:v['calibration_valid'] for k,v in cal['agents'].items()}=={'Camera':True,'Seg':True,'GNSS':False,'IMU':True}
hm=read(handoff/'manifest.json')
for name,r in hm['files'].items():assert sha(handoff/name)==r['sha256']
with np.load(handoff/'compact_training_checkpoint.npz',allow_pickle=False) as z:
 assert z['calibration_valid'].tolist()==[True,True,False,True]
 for key in ['prob_normal','total','aleatoric','epistemic']:assert np.isnan(z[key][:,2]).all()
 assert np.all(z['partition'][z['is_pseudo']]==1)

ids=sorted(manifest['FIT_NORMAL']);rng=np.random.Generator(np.random.PCG64(2027));perm=rng.permutation(len(ids))
val=sorted(ids[int(i)] for i in perm[:3]);train=sorted(set(ids)-set(val))
assert len(train)==12 and len(val)==3 and not(set(ids)&set(manifest['CAL_NORMAL']))
mapping={sid:('GRAPH_TRAIN' if sid in train else 'GRAPH_VALIDATION' if sid in val else 'AGENT_CAL_ONLY') for sid in manifest['sorted_canonical_ids']}
split={'schema_version':1,'source_N20_manifest_sha256':sha(N20/'frozen_dataset_manifest.json'),'seed':2027,'rng':'NumPy Generator(PCG64(2027))','numpy_version':np.__version__,
 'rule':'sort frozen FIT IDs; permute once; first 3 positions are graph validation; remaining 12 graph train; sort each output list',
 'permutation_indices':perm.tolist(),'sorted_FIT_ids':ids,'GRAPH_TRAIN':train,'GRAPH_VALIDATION':val,'AGENT_CAL_ONLY':manifest['CAL_NORMAL'],'scenario_role':mapping,
 'pseudo_inherits_parent_role':True,'tick_level_random_splitting':False,'held_out_unit':'whole scenario',
 'conditional_validation_limit':'Frozen upstream one-class models used all 15 FIT scenarios, including these 3 validation scenarios. This holds out graph-supervised fitting only; it is not full-pipeline unseen-scenario evaluation. No upstream refitting is performed.',
 'CAL_usage':'existing agent calibration only; no graph fitting, early stopping, threshold selection, or graph-development metrics'}
save('split_manifest.json',split)

